  1	/**
  2	 * zephyrBrowserstackSync.mjs — SFCC-751 QA pipeline: BrowserStack Test
  3	 * Observability -> Zephyr Scale execution sync, with automatic Jira defect
  4	 * filing on failure.
  5	 *
  6	 * Invoked once per triggering QA workflow run, from
  7	 * .github/workflows/zephyr-results-sync.yml. Not a check/gate — a sync job:
  8	 * die() means the sync itself failed (the workflow step fails); a completed
  9	 * run with zero Zephyr-tagged tests is a normal pass, not an error.
 10	 *
 11	 * Why this exists instead of BrowserStack's native Zephyr integration: that
 12	 * integration's setup flow only accepts a Jira host, with no field for a
 13	 * custom Zephyr API base URL — and this org's Zephyr Scale instance is
 14	 * DE-hosted (https://de.api.zephyrscale.smartbear.com), not one of
 15	 * BrowserStack's supported regions. See .docs/temp/SFCC-751-implementation-spec.md.
 16	 *
 17	 * Zephyr key mapping: reads each BrowserStack test result's `tags` array for
 18	 * a `@zephyr:<KEY>` tag (confirmed via BrowserStack's Get Tests API to carry
 19	 * real Playwright source-file tags, not synthesized ones). A result with no
 20	 * such tag is skipped — not every spec participates in Zephyr sync.
 21	 *
 22	 * Evidence: Zephyr Scale's REST API has no attachment endpoint (confirmed —
 23	 * four independent SmartBear community threads, ~2022-2024, nothing newer
 24	 * found contradicting it). Evidence goes on the *Jira* defect instead;
 25	 * Zephyr's execution `comment` field only gets a link to the BrowserStack
 26	 * session and, if one was filed, the Jira defect.
 27	 *
 28	 * Assignee: the failing test's @SFCC-NNN story's current Jira assignee. If
 29	 * unassigned, falls back to the last committer of the failing spec file
 30	 * itself (git blame) — NOT the app code the test exercises, which isn't
 31	 * derivable from a black-box E2E failure without deeper instrumentation;
 32	 * a deliberately narrower, honest scope for the fallback. The spec file is
 33	 * located by grepping for the test's title rather than trusting an assumed
 34	 * BrowserStack response field for it (see NOT YET LIVE-VERIFIED below).
 35	 *
 36	 * NOT YET LIVE-VERIFIED: no BrowserStack build has ever existed under this
 37	 * account's configured project (confirmed via a live GET /ext/v1/projects
 38	 * call, 2026-08-25 — zero builds anywhere). getTestRuns() below now follows
 39	 * the documented Get Tests response shape (a paginated `hierarchy[]` of
 40	 * suites, each with `children[]` test entries under `details` — NOT a flat
 41	 * `test_runs`/`tests` array, which the first version of this script wrongly
 42	 * assumed and which would have silently synced zero results against a real
 43	 * build) per https://www.browserstack.com/docs/test-reporting-and-analytics/api/get-tests,
 44	 * cross-checked against a second independent source, 2026-08-25 — but still
 45	 * not exercised against a real payload. Treat the first real run as the
 46	 * actual verification, per Deliverable 3 of the implementation spec.
 47	 *
 48	 * Required env vars: BROWSERSTACK_USERNAME, BROWSERSTACK_ACCESS_KEY,
 49	 * BROWSERSTACK_PROJECT_NAME, BROWSERSTACK_BUILD_NAME, ZEPHYR_API_KEY,
 50	 * ZEPHYR_API_URL (base host + /testcases path; /testexecutions is derived
 51	 * from it), JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN.
 52	 * GITHUB_SERVER_URL/GITHUB_REPOSITORY/GITHUB_RUN_ID are supplied
 53	 * automatically by Actions.
 54	 */
 55	import { execFileSync } from 'node:child_process';
 56	import { appendFileSync } from 'node:fs';
 57	
 58	const die = (msg) => {
 59	  console.error(`✗ zephyr-browserstack-sync: ${msg}`);
 60	  process.exit(1);
 61	};
 62	const warn = (msg) => console.error(`::warning::zephyr-browserstack-sync: ${msg}`);
 63	const log = (msg) => console.log(`zephyr-browserstack-sync: ${msg}`);
 64	
 65	const REQUIRED_ENV = [
 66	  'BROWSERSTACK_USERNAME',
 67	  'BROWSERSTACK_ACCESS_KEY',
 68	  'BROWSERSTACK_PROJECT_NAME',
 69	  'BROWSERSTACK_BUILD_NAME',
 70	  'ZEPHYR_API_KEY',
 71	  'ZEPHYR_API_URL',
 72	  'JIRA_URL',
 73	  'JIRA_AUTOMATION_EMAIL',
 74	  'JIRA_AUTOMATION_API_TOKEN',
 75	];
 76	for (const key of REQUIRED_ENV) {
 77	  if (!process.env[key]) die(`missing required env var ${key}`);
 78	}
 79	
 80	const {
 81	  BROWSERSTACK_USERNAME,
 82	  BROWSERSTACK_ACCESS_KEY,
 83	  BROWSERSTACK_PROJECT_NAME,
 84	  BROWSERSTACK_BUILD_NAME,
 85	  ZEPHYR_API_KEY,
 86	  ZEPHYR_API_URL,
 87	  JIRA_URL,
 88	  JIRA_AUTOMATION_EMAIL,
 89	  JIRA_AUTOMATION_API_TOKEN,
 90	  GITHUB_SERVER_URL,
 91	  GITHUB_REPOSITORY,
 92	  GITHUB_RUN_ID,
 93	} = process.env;
 94	
 95	const ZEPHYR_PROJECT_KEY = 'SFCC';
 96	const ZEPHYR_TESTEXECUTIONS_URL = ZEPHYR_API_URL.replace(/\/testcases\/?$/, '/testexecutions');
 97	const BROWSERSTACK_API = 'https://api-automation.browserstack.com';
 98	const bstackAuth = 'Basic ' + Buffer.from(`${BROWSERSTACK_USERNAME}:${BROWSERSTACK_ACCESS_KEY}`).toString('base64');
 99	const jiraAuth = 'Basic ' + Buffer.from(`${JIRA_AUTOMATION_EMAIL}:${JIRA_AUTOMATION_API_TOKEN}`).toString('base64');
100	
101	/** Thin JSON-fetch wrapper — throws with the response body on a non-2xx status. */
102	async function fetchJson(url, opts = {}) {
103	  const res = await fetch(url, opts);
104	  const text = await res.text();
105	  let body;
106	  try {
107	    body = text ? JSON.parse(text) : {};
108	  } catch {
109	    body = text;
110	  }
111	  if (!res.ok) {
112	    throw new Error(`${opts.method || 'GET'} ${url} -> ${res.status}: ${JSON.stringify(body).slice(0, 300)}`);
113	  }
114	  return body;
115	}
116	
117	async function findProjectId() {
118	  let page;
119	  do {
120	    const url = new URL(`${BROWSERSTACK_API}/ext/v1/projects`);
121	    if (page) url.searchParams.set('next_page', page);
122	    const { projects, pagination } = await fetchJson(url, { headers: { Authorization: bstackAuth } });
123	    const match = (projects || []).find((p) => p.name === BROWSERSTACK_PROJECT_NAME);
124	    if (match) return match.id;
125	    page = pagination?.has_next ? pagination.next_page : null;
126	  } while (page);
127	  return null;
128	}
129	
130	async function findBuild(projectId) {
131	  const url = new URL(`${BROWSERSTACK_API}/ext/v1/projects/${projectId}/builds`);
132	  url.searchParams.set('unique_build_names', BROWSERSTACK_BUILD_NAME);
133	  const body = await fetchJson(url, { headers: { Authorization: bstackAuth } });
134	  const builds = body.builds || [];
135	  return builds[0] || null;
136	}
137	
138	async function getTestRuns(buildId) {
139	  const tests = [];
140	  let page;
141	  do {
142	    const url = new URL(`${BROWSERSTACK_API}/ext/v1/builds/${buildId}/testRuns`);
143	    if (page) url.searchParams.set('next_page', page);
144	    const { hierarchy, pagination } = await fetchJson(url, { headers: { Authorization: bstackAuth } });
145	    for (const suite of hierarchy || []) {
146	      for (const child of suite.children || []) {
147	        const details = child.details || {};
148	        const failureLogs = (details.retries || []).flatMap((retry) => retry.logs?.TEST_FAILURE || []);
149	        tests.push({
150	          name: child.display_name,
151	          tags: details.tags || [],
152	          status: details.status,
153	          session_url: details.observability_url || null,
154	          error_message: failureLogs.join('\n') || null,
155	        });
156	      }
157	    }
158	    page = pagination?.has_next ? pagination.next_page : null;
159	  } while (page);
160	  return tests;
161	}
162	
163	// BrowserStack's Test Observability API strips the leading '@' from
164	// Playwright tags — confirmed against a real local run's test_tags
165	// (2026-08-25): ['SFCC-751', 'homepage', 'p1', 'zephyr:SFCC-T285'], not
166	// ['@SFCC-751', ...]. The source spec files still carry '@'-prefixed tags
167	// (Playwright's own convention); only the API response has them stripped.
168	function zephyrKeyTag(tags) {
169	  const tag = (tags || []).find((t) => t.startsWith('zephyr:'));
170	  return tag ? tag.slice('zephyr:'.length) : null;
171	}
172	
173	function storyKeyTag(tags) {
174	  const tag = (tags || []).find((t) => /^SFCC-\d+$/.test(t));
175	  return tag || null;
176	}
177	
178	async function postZephyrExecution({ testCaseKey, statusName, comment }) {
179	  return fetchJson(ZEPHYR_TESTEXECUTIONS_URL, {
180	    method: 'POST',
181	    headers: { Authorization: `Bearer ${ZEPHYR_API_KEY}`, 'Content-Type': 'application/json' },
182	    body: JSON.stringify({ projectKey: ZEPHYR_PROJECT_KEY, testCaseKey, statusName, comment }),
183	  });
184	}
185	
186	async function jiraStoryAssignee(storyKey) {
187	  try {
188	    const issue = await fetchJson(`${JIRA_URL}/rest/api/3/issue/${storyKey}?fields=assignee`, {
189	      headers: { Authorization: jiraAuth, Accept: 'application/json' },
190	    });
191	    return issue.fields?.assignee?.accountId || null;
192	  } catch (err) {
193	    warn(`could not read assignee for ${storyKey}: ${String(err.message).slice(0, 200)}`);
194	    return null;
195	  }
196	}
197	
198	/** Last committer of the failing spec file — see the file-level doc comment
199	 * for why this stays scoped to the test file, not the app code under test. */
200	function findSpecFile(testName) {
201	  try {
202	    const out = execFileSync('grep', ['-rl', '--include=*.spec.js', '-F', testName, 'e2e/tests/zimm'], {
203	      encoding: 'utf8',
204	    }).trim();
205	    return out.split('\n')[0] || null;
206	  } catch {
207	    return null; // grep exits non-zero when nothing matches
208	  }
209	}
210	
211	function gitBlameFallbackEmail(specPath) {
212	  try {
213	    return execFileSync('git', ['log', '-1', '--format=%ae', '--', specPath], { encoding: 'utf8' }).trim() || null;
214	  } catch (err) {
215	    warn(`git blame fallback failed for ${specPath}: ${err.message}`);
216	    return null;
217	  }
218	}
219	
220	async function jiraAccountIdForEmail(email) {
221	  try {
222	    const users = await fetchJson(`${JIRA_URL}/rest/api/3/user/search?query=${encodeURIComponent(email)}`, {
223	      headers: { Authorization: jiraAuth, Accept: 'application/json' },
224	    });
225	    return users[0]?.accountId || null;
226	  } catch (err) {
227	    warn(`could not resolve Jira account for ${email}: ${String(err.message).slice(0, 200)}`);
228	    return null;
229	  }
230	}
231	
232	async function resolveAssignee(storyKey, testName) {
233	  const storyAssignee = await jiraStoryAssignee(storyKey);
234	  if (storyAssignee) return storyAssignee;
235	  const specPath = findSpecFile(testName);
236	  const email = specPath ? gitBlameFallbackEmail(specPath) : null;
237	  return email ? jiraAccountIdForEmail(email) : null;
238	}
239	
240	async function fileDefect({ storyKey, testName, sessionUrl, errorText, assigneeAccountId }) {
241	  const runUrl = `${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}`;
242	  const body = {
243	    fields: {
244	      project: { key: ZEPHYR_PROJECT_KEY },
245	      issuetype: { name: 'Bug' },
246	      summary: `[Automated] BrowserStack failure: ${testName}`,
247	      description: {
248	        type: 'doc',
249	        version: 1,
250	        content: [
251	          {
252	            type: 'paragraph',
253	            content: [
254	              {
255	                type: 'text',
256	                text:
257	                  `Automatically filed from a BrowserStack E2E failure on ${storyKey}.\n\n` +
258	                  `BrowserStack session: ${sessionUrl || '(no session URL available)'}\n` +
259	                  `GitHub Actions run: ${runUrl}\n\n` +
260	                  `Error:\n${(errorText || '(no error text captured)').slice(0, 3000)}`,
261	              },
262	            ],
263	          },
264	        ],
265	      },
266	      // 'Relates' is Jira Cloud's common default link-type name — not
267	      // confirmed against this specific instance's configured types.
268	      issuelinks: [{ type: { name: 'Relates' }, outwardIssue: { key: storyKey } }],
269	      ...(assigneeAccountId ? { assignee: { accountId: assigneeAccountId } } : {}),
270	    },
271	  };
272	  return fetchJson(`${JIRA_URL}/rest/api/3/issue`, {
273	    method: 'POST',
274	    headers: { Authorization: jiraAuth, 'Content-Type': 'application/json' },
275	    body: JSON.stringify(body),
276	  });
277	}
278	
279	function summaryLine(text) {
280	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, text + '\n');
281	  log(text);
282	}
283	
284	async function main() {
285	  const projectId = await findProjectId();
286	  if (!projectId) die(`no BrowserStack project named '${BROWSERSTACK_PROJECT_NAME}' found`);
287	
288	  const build = await findBuild(projectId);
289	  if (!build) {
290	    // e2e-browserstack is conditionally gated — many QA runs won't have
291	    // a BrowserStack build at all. That's expected, not an error.
292	    summaryLine(`No BrowserStack build named '${BROWSERSTACK_BUILD_NAME}' found — nothing to sync.`);
293	    return;
294	  }
295	
296	  const testRuns = await getTestRuns(build.id);
297	  summaryLine(`## Zephyr sync — build \`${BROWSERSTACK_BUILD_NAME}\` (${testRuns.length} tests)`);
298	  summaryLine('| Test | Zephyr key | Status | Zephyr execution | Defect |');
299	  summaryLine('|---|---|---|---|---|');
300	
301	  for (const test of testRuns) {
302	    const zephyrKey = zephyrKeyTag(test.tags);
303	    if (!zephyrKey) continue; // this spec doesn't participate in Zephyr sync
304	
305	    const storyKey = storyKeyTag(test.tags);
306	    // Only map terminal statuses. BrowserStack Test Observability also
307	    // reports 'skipped'/'running'/'unknown' (e.g. a mobile-only spec's
308	    // desktop-project entry, or a still-in-progress run) — treating those
309	    // as 'Fail' would file false Zephyr failures and Jira defects for
310	    // tests that never actually ran or failed.
311	    if (test.status !== 'passed' && test.status !== 'failed') {
312	      summaryLine(`| ${test.name} | ${zephyrKey} | ${test.status} (skipped — non-terminal) | | |`);
313	      continue;
314	    }
315	    const statusName = test.status === 'passed' ? 'Pass' : 'Fail';
316	    const sessionUrl = test.session_url;
317	
318	    let execution;
319	    try {
320	      execution = await postZephyrExecution({
321	        testCaseKey: zephyrKey,
322	        statusName,
323	        comment: `BrowserStack session: ${sessionUrl || '(unavailable)'}`,
324	      });
325	    } catch (err) {
326	      warn(`Zephyr execution POST failed for ${zephyrKey}: ${String(err.message).slice(0, 300)}`);
327	      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | **sync failed** | |`);
328	      continue;
329	    }
330	
331	    if (statusName !== 'Fail' || !storyKey) {
332	      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | |`);
333	      continue;
334	    }
335	
336	    const assigneeAccountId = await resolveAssignee(storyKey, test.name);
337	    try {
338	      const defect = await fileDefect({
339	        storyKey,
340	        testName: test.name,
341	        sessionUrl,
342	        errorText: test.error_message || '',
343	        assigneeAccountId,
344	      });
345	      summaryLine(
346	        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | ${JIRA_URL}/browse/${
347	          defect.key
348	        } |`,
349	      );
350	    } catch (err) {
351	      warn(`Jira defect creation failed for ${test.name}: ${String(err.message).slice(0, 300)}`);
352	      summaryLine(
353	        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | **defect filing failed** |`,
354	      );
355	    }
356	  }
357	}
358	
359	main().catch((err) => die(err.stack || err.message));

