     5	
     6	const { test, expect } = require('@playwright/test');
     7	const { ListMenuPage } = require('../../../../support/pages/ListMenuPage');
     8	const sitePrefixes = require('../../../../fixtures/sitePrefixes');
     9	
    10	const TAGS = ['@SFCC-751', '@homepage', '@p1', '@zephyr:SFCC-T285'];
    11	const ALL_PREFIXES = Object.values(sitePrefixes)
    12	  .map((site) => site.urlPrefix)
    13	  .filter(Boolean);
    14	
    15	test.describe("Header navigation links carry the site's URL prefix", () => {
    16	  for (const [siteKey, { urlPrefix }] of Object.entries(sitePrefixes)) {
    17	    test(`Header navigation links carry the site's URL prefix on ${siteKey}`, { tag: TAGS }, async ({ page }) => {
    18	      const listMenu = new ListMenuPage(page);
    19	      await listMenu.goToSite(urlPrefix);
    20	
    21	      const hrefs = await listMenu.getNavLinkHrefs();
    22	      expect(hrefs.length).toBeGreaterThan(0);
    23	
    24	      for (const href of hrefs) {
    25	        if (urlPrefix) {
    26	          // Some nav items render an extra wrapper link to the bare site
    27	          // root (e.g. /us, no trailing slash — a dropdown-chevron target),
    28	          // alongside the real /us/category/... link. Both are within-site,
    29	          // which is what this test actually checks — reject only a href
    30	          // that starts with the prefix but has no separator after it
    31	          // (e.g. /usable would wrongly pass a plain startsWith(prefix)).
    32	          expect(href === urlPrefix || href.startsWith(`${urlPrefix}/`)).toBe(true);
    33	        } else {
    34	          // au is root-prefixed — its links must not carry any other site's prefix
    35	          expect(ALL_PREFIXES.some((otherPrefix) => href === otherPrefix || href.startsWith(`${otherPrefix}/`))).toBe(
    36	            false,
    37	          );
    38	        }
    39	      }
    40	    });
    41	  }
    42	});
=== mobile spec ===
     1	/*
     2	 * Deliberately a separate file/title from
     3	 * ../desktop/SFCC-751_header-nav-site-prefix.spec.js, not a mobile
     4	 * variant of the same test. BrowserStack Test Observability groups
     5	 * results by test title across "reruns" regardless of Playwright project
     6	 * — a shared title running on both chromium and mobile-chrome collapses
     7	 * to one row showing only the last-recorded status, hiding whichever one
     8	 * didn't "win" (confirmed against real build data, 2026-08-25). This
     9	 * file's location under mobile/ means chromium's own testIgnore in
    10	 * playwright.config.js never collects it at all — true separation, not a
    11	 * runtime skip, which is what actually avoids the collision (a same-file,
    12	 * distinct-title approach was tried and rejected — the underlying test()
    13	 * call still gets collected, and skipped, on the other project either
    14	 * way).
    15	 *
    16	 * No @zephyr: tag — SFCC-T285 covers the desktop scenario this pipeline
    17	 * was built to validate; this gap has no Zephyr test case of its own yet.
    18	 */
    19	
    20	const { test, expect } = require('@playwright/test');
    21	const { MobileDrawerMenuPage } = require('../../../../support/pages/MobileDrawerMenuPage');
    22	const { activeSiteKey } = require('../../../../fixtures/site');
    23	const sitePrefixes = require('../../../../fixtures/sitePrefixes');
    24	
    25	test.describe('Mobile header navigation', () => {
    26	  test(
    27	    'Mobile header nav exposes site-prefixed category browsing links',
    28	    { tag: ['@SFCC-751', '@homepage', '@p1'] },
    29	    async ({ page }) => {
    30	      const drawerMenu = new MobileDrawerMenuPage(page);
    31	      await drawerMenu.goToSite(sitePrefixes[activeSiteKey()].urlPrefix);
    32	
    33	      // Expected to fail today: the mobile drawer currently has no
    34	      // category navigation content at all (only account/store-locator
    35	      // links — confirmed 2026-08-25). A known, already-documented gap
    36	      // against HPC-018 in overrides/app/components/header/index.tsx's
    37	      // own comments, not introduced by this spec. This test exists to
    38	      // make that gap visible in CI rather than silently untested, and
    39	      // should start passing on its own once mobile category nav ships.
    40	      const hrefs = await drawerMenu.getDrawerLinkHrefs();
    41	      const categoryHrefs = hrefs.filter((href) => href.includes('/category/'));
    42	      expect(categoryHrefs.length).toBeGreaterThan(0);
    43	    },
    44	  );
    45	});

