=== feature file ===
     1	@SFCC-751 @homepage @p1 @zephyr:SFCC-T285
     2	Feature: Header navigation carries the correct site URL prefix
     3	  As a shopper browsing any Zimmermann storefront
     4	  I want every header navigation link to stay within my current site
     5	  So that I am never routed to the wrong region's catalogue, pricing, or checkout
     6	
     7	  Background:
     8	    Given I am on the Zimmermann storefront
     9	
    10	  Scenario Outline: Header navigation links carry the site's URL prefix
    11	    Given I am viewing the "<site>" storefront
    12	    When the header navigation loads
    13	    Then every navigation link starts with the "<urlPrefix>" prefix
    14	
    15	    Examples:
    16	      | site   | urlPrefix |
    17	      | au     |           |
    18	      | us     | /us       |
    19	      | usIntl | /en-ca    |
    20	      | uk     | /uk       |
    21	      | enEu   | /en-eu    |
    22	      | frEu   | /fr-eu    |
    23	      | itEu   | /it-eu    |
    24	      | esEu   | /es-eu    |
    25	      | euIntl | /en-ch    |
    26	      | hk     | /hk       |
    27	      | me     | /en-ae    |

=== computeBuildName.mjs ===
     1	/**
     2	 * computeBuildName.mjs — derives a human-readable BrowserStack build name
     3	 * from a primary Jira key.
     4	 *
     5	 * Output shape (printed to stdout, nothing else): the suffix that plugs
     6	 * directly into browserstack.yml's `buildName: "Sprint-${SPRINT_NUMBER}"`
     7	 * template — e.g. for SPRINT_NUMBER="3-SFCC-751-SFCC-T285 - QA Pipeline —
     8	 * Playwright spec…", the real build name becomes
     9	 * "Sprint-3-SFCC-751-SFCC-T285 - QA Pipeline — Playwright spec…".
    10	 *
    11	 * Called only from qa.yml's e2e-browserstack job (which SETS
    12	 * SPRINT_NUMBER, and so the real build name). zephyr-results-sync.yml does
    13	 * NOT call this a second time — it downloads the exact string this job
    14	 * computed as a build artifact instead. It used to recompute it
    15	 * independently, but that job deliberately checks out develop rather than
    16	 * the PR branch (see its own comment on why), so findZephyrKeys() below
    17	 * would see a different e2e/tests/zimm spec-file set than this job's PR
    18	 * checkout whenever a PR adds or renames a Zephyr-tagged spec — a
    19	 * guaranteed mismatch while such a PR is open, not a rare race condition
    20	 * (CodeRabbit flagged this correctly, 2026-08-25; an earlier version of
    21	 * this comment mischaracterised the risk as a rare same-issue-changes-
    22	 * mid-flight race). Artifact-passing removes the drift instead of just
    23	 * accepting it.
    24	 *
    25	 * Usage: node scripts/computeBuildName.mjs <JIRA_KEY>
    26	 * Requires: JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN
    27	 *
    28	 * Never fails the caller — a Jira lookup problem degrades to a plainer
    29	 * name (e.g. "unknown-SFCC-751") rather than blocking a test run that has
    30	 * nothing to do with build-name cosmetics.
    31	 */
    32	import { execFileSync } from 'node:child_process';
    33	
    34	// Confirmed live via a real jira_search_fields call against this Jira
    35	// instance (2026-08-25) — Jira Cloud has no stable "sprint" field alias;
    36	// this customfield ID is instance-specific, not a safe value to assume
    37	// for any other Jira site.
    38	const SPRINT_FIELD = 'customfield_10020';
    39	const MAX_SUMMARY_LEN = 40;
    40	
    41	const [jiraKey] = process.argv.slice(2);
    42	if (!jiraKey) {
    43	  console.error('usage: computeBuildName.mjs <JIRA_KEY>');
    44	  process.exit(1);
    45	}
    46	
    47	function fallback(reason) {
    48	  console.error(`computeBuildName: ${reason} — falling back to a plain name`);
    49	  console.log(`unknown-${jiraKey}`);
    50	  process.exit(0);
    51	}
    52	
    53	const { JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN } = process.env;
    54	if (!JIRA_URL || !JIRA_AUTOMATION_EMAIL || !JIRA_AUTOMATION_API_TOKEN) {
    55	  fallback('missing JIRA_URL/JIRA_AUTOMATION_EMAIL/JIRA_AUTOMATION_API_TOKEN');
    56	}
    57	
    58	function truncate(text, max) {
    59	  return text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text;
    60	}
    61	
    62	/** Zephyr key(s) tagged on any spec that also carries this Jira key's tag —
    63	 * greps the same way scripts/zephyrBrowserstackSync.mjs locates a spec by
    64	 * test name, since there's no other cross-reference between a story and
